content.applied_patch:
--- a/rtl/sequence.sv
+++ b/rtl/sequence.sv
@@ -17,7 +17,7 @@

     always@(posedge clk or negedge rst) begin
         if(~rst)
-            state <= S0_5;
+            state <= S0;
         else
             state <= nstate;
     end

--- a/rtl/sequence.sv
+++ b/rtl/sequence.sv
@@ -54,7 +54,7 @@
                 S0, S0_5, S1: {out1, out2, out3} = 0;
                 S1_5        : {out1, out2, out3} = ~sel? 3'b100: 3'b000;
                 S2          : {out1, out2, out3} = ~sel? 3'b101: 3'b000;
-                S2_5        : {out1, out2, out3} = ~sel? 3'b101: 3'b000;
+                S2_5        : {out1, out2, out3} = ~sel? 3'b101: 3'b010;
                 S3          : {out1, out2, out3} = ~sel? 3'b101: 3'b011;
                 default     : {out1, out2, out3} = 3'b000;
             endcase

--- a/rtl/sequence.sv
+++ b/rtl/sequence.sv
@@ -41,6 +41,8 @@
                               d1? S2_5:
                               d2? S3:
                               nstate;
+            S2_5   : nstate = S0;
+            S3     : nstate = S0;
             default: nstate = state;
         endcase
     end

--- a/rtl/sequence.sv
+++ b/rtl/sequence.sv
@@ -55,7 +55,7 @@
                 S1_5        : {out1, out2, out3} = ~sel? 3'b100: 3'b000;
